"use strict";(self.webpackChunkgeaflow_website=self.webpackChunkgeaflow_website||[]).push([[4628],{4110:e=>{e.exports=JSON.parse('{"permalink":"/zh-CN/blog/31","source":"@site/blog/31.md","title":"Graph4Stream: Accelerating Stream Computing with Graph-Based Approaches","description":"Author Dongshuo.","date":"2025-03-25T00:00:00.000Z","tags":[],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Graph4Stream: Accelerating Stream Computing with Graph-Based Approaches","date":"2025-3-25"},"unlisted":false,"prevItem":{"title":"Streaming Graph Computing Engine GeaFlow v0.6.4 Released: Supports Relational Access to Graph Data, Incremental Matching Optimizes Real-Time Processing","permalink":"/zh-CN/blog/32"},"nextItem":{"title":"Stream4Graph: Incremental Computation on Dynamic Graphs","permalink":"/zh-CN/blog/27"}}')},5524:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>p,frontMatter:()=>s,metadata:()=>a,toc:()=>c});var a=t(4110),i=t(4848),r=t(8453);const s={title:"Graph4Stream: Accelerating Stream Computing with Graph-Based Approaches",date:"2025-3-25"},o=void 0,l={authorsImageUrls:[]},c=[{value:"Stream Computing Engine: Flink",id:"stream-computing-engine-flink",level:2},{value:"Stream Graph Computing Engine: GeaFlow",id:"stream-graph-computing-engine-geaflow",level:2},{value:"Graph Computing &amp; Stream Graphs",id:"graph-computing--stream-graphs",level:3},{value:"GeaFlow Architecture",id:"geaflow-architecture",level:3},{value:"GeaFlow Performance Test",id:"geaflow-performance-test",level:2},{value:"Conclusion and Future Work",id:"conclusion-and-future-work",level:2},{value:"References",id:"references",level:2}];function h(e){const n={a:"a",blockquote:"blockquote",code:"code",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/8237/1741852109942-9310f385-a0c2-4c32-987f-77b5c9df911a.png",alt:""})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"Author: Kunyu; Reviewer: Dongshuo."}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:["In a previous article ",(0,i.jsx)(n.a,{href:"https://zhuanlan.zhihu.com/p/27618053733",children:'"Stream4Graph: Incremental Computation on Dynamic Graphs"'}),', we introduced how introducing incremental computation into graph computing\u2014essentially combining "graphs + streams"\u2014allowed GeaFlow to significantly outperform Spark GraphX in terms of performance. Now, the question arises: when we introduce graph computing capabilities into stream computing\u2014combining "streams + graphs"\u2014how does GeaFlow compare to Flink\'s associative computation performance?']}),"\n",(0,i.jsxs)(n.p,{children:["In today\u2019s era, data is being generated at an unprecedented speed and scale, and real-time processing of massive datasets has wide applications in various fields such as anomaly detection, search recommendations, and financial transactions. As one of the core technologies for real-time data processing, ",(0,i.jsx)(n.strong,{children:"stream computing"})," has become increasingly important."]}),"\n",(0,i.jsx)(n.p,{children:"Unlike batch processing, which waits for all data to arrive before computation, stream computing partitions continuously generated data streams into micro-batches and performs incremental computations on each batch. This computational characteristic gives stream computing high throughput and low latency. Common stream computing engines include Flink and Spark Streaming, both of which process data using tabular representations. However, as stream computing applications deepen, more and more scenarios involve computing complex relationships among large datasets, leading to significant performance degradation in table-based stream engines."}),"\n",(0,i.jsx)(n.p,{children:"GeaFlow, an open-source stream graph computing engine developed by Ant Group's graph computing team, combines graph and stream computing to provide an efficient framework for stream graph processing, significantly improving computational performance. Below, we will introduce the limitations of traditional stream computing engines in relational computation, explain the principles behind GeaFlow's efficiency, and present performance comparisons."}),"\n",(0,i.jsx)(n.h2,{id:"stream-computing-engine-flink",children:"Stream Computing Engine: Flink"}),"\n",(0,i.jsx)(n.p,{children:"Flink is a classic table-based stream processing engine. It slices incoming data streams into micro-batches and processes the data in each batch incrementally. During execution, Flink translates computation tasks into directed graphs composed of basic operators like map, filter, and join. Each operator receives input from upstream and sends output downstream. Incremental data passes through all operators to produce results for the current batch."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/35234/1741541936849-f9e0ae71-d25d-4789-b9c6-ed0380140f2a.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"Flink Incremental Computation"}),"\n",(0,i.jsxs)(n.p,{children:["We take the k-Hop algorithm as an example to illustrate Flink\u2019s computation process. A k-Hop relationship refers to a path that spans k steps\u2014such as a chain of acquaintances in social networks or a sequence of fund transfers in transaction analysis. Assuming a 2-hop relationship, with input data in the format ",(0,i.jsx)(n.code,{children:"src dst"})," representing pairwise relationships, Flink executes the following SQL:"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-sql",children:"-- create source table\nCREATE TABLE edge (\n    src int,\n    dst int\n) WITH (\n);\n\nCREATE VIEW `v_view` (`vid`) AS\nSELECT distinct * from\n(\nSELECT `src` FROM `edge`\nUNION ALL\nSELECT `dst` FROM `edge`\n);\n\nCREATE VIEW `e_view` (`src`, `dst`) AS\nSELECT `src`, `dst` FROM `edge`;\n\nCREATE VIEW `join1_edge`(`id1`, `dst`) AS SELECT `v`.`vid`, `e`.`dst`\nFROM `v_view` AS `v` INNER JOIN `e_view` AS `e`\nON `v`.`vid` = `e`.`src`;\n\nCREATE VIEW `join1`(`id1`, `id2`) AS SELECT `e`.`id1`, `v`.`vid`\nFROM `join1_edge` AS `e` INNER JOIN `v_view` AS `v`\nON `e`.`dst` = `v`.`vid`;\n\nCREATE VIEW `join2_edge`(`id1`, `id2`, `dst`) AS SELECT `v`.`id1`, `v`.`id2`, `e`.`dst`\nFROM `join1` AS `v` INNER JOIN `e_view` AS `e`\nON `v`.`id2` = `e`.`src`;\n\nCREATE VIEW `join2`(`id1`, `id2`, `id3`) AS SELECT `e`.`id1`, `e`.`id2`, `v`.`vid`\nFROM `join2_edge` AS `e` INNER JOIN `v_view` AS `v`\nON `e`.`dst` = `v`.`vid`;\n\n"})}),"\n",(0,i.jsx)(n.p,{children:"The execution plan is shown below. It consists of operators such as Aggregate, Calc, and Join. Data flows through each operator to yield incremental results. The core operator, Join, is responsible for relationship lookups. Let's examine how the Join operator works."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/35234/1740550683257-198617cb-b66b-4997-86f7-d41df94f0fb1.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"Flink Execution Plan"}),"\n",(0,i.jsx)(n.p,{children:"As shown below, the Join operator has two input streams: LeftInput and RightInput, corresponding to the left and right tables of the join. When data arrives from upstream, the operator begins computation. Taking the left input stream as an example, the data is first stored in LeftStateView. Then, the operator queries RightStateView for data that satisfies the join condition. This querying process requires scanning through RightStateView, and the resulting joined data is passed to the next operator."}),"\n",(0,i.jsx)(n.p,{children:"The main performance bottleneck lies in scanning RightStateView. LeftStateView and RightStateView store the left and right tables of the join, respectively. As data continuously flows in, the size of StateViews grows, causing scan times to increase dramatically and severely degrading system performance."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/35234/1741589034132-1969e973-94dd-42ca-b506-ebe4594d87a8.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"Flink Join Operator Implementation"}),"\n",(0,i.jsx)(n.h2,{id:"stream-graph-computing-engine-geaflow",children:"Stream Graph Computing Engine: GeaFlow"}),"\n",(0,i.jsx)(n.h3,{id:"graph-computing--stream-graphs",children:"Graph Computing & Stream Graphs"}),"\n",(0,i.jsx)(n.p,{children:"Graph computing is a computational paradigm based on graph data structures. A graph G(V,E) consists of a set of vertices V and edges E, where edges represent relationships between data. Using the public dataset web-Google as an example, each line contains two numbers representing a hyperlink between two web pages. As shown below, the left side shows raw data, which is traditionally modeled as a two-column table. In contrast, graph modeling treats web pages as vertices and hyperlinks as edges, forming a web link graph. In the tabular model, relationship computation is done via joins, which require scanning tables. In graph computing, relationships are directly stored in edges, eliminating the need for scans."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/35234/1741544451333-05f87f7e-8c8b-41fb-a27b-051b6df8e5da.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"Table Modeling vs. Graph Modeling"}),"\n",(0,i.jsxs)(n.p,{children:["A ",(0,i.jsx)(n.strong,{children:"stream graph"})," is the application of graph computing to streaming scenarios. It divides the graph into historical and incremental components based on data stream updates. For example, if the first two rows have been processed and we are now handling the third row, the historical graph is built from the first two rows, and the incremental graph is formed by the third row. Together, they constitute the full graph. Applying incremental graph algorithms on stream graphs enables efficient, real-time computation."]}),"\n",(0,i.jsx)(n.h3,{id:"geaflow-architecture",children:"GeaFlow Architecture"}),"\n",(0,i.jsx)(n.p,{children:"The GeaFlow engine\u2019s computation flow consists of stream data input, distributed incremental graph computation, and incremental result output. Like traditional stream engines, real-time data is sliced into micro-batches by window. For each batch, the data is parsed into vertices and edges to form an incremental graph. This incremental graph and the historical graph (built from previous data) together form the complete stream graph. The computation framework applies incremental graph algorithms on the stream graph to yield incremental results, which are then output and added to the historical graph."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/35234/1740932875376-6633b307-c309-4ae7-be5e-d0b96a66409a.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"GeaFlow Incremental Computation"}),"\n",(0,i.jsx)(n.p,{children:"The GeaFlow computation framework is a vertex-centric iterative model. It starts with vertices in the incremental graph. In each iteration, each vertex maintains its own state and performs computation based on its associated historical and incremental graph data. The result is then passed to neighboring vertices via message passing to trigger the next iteration."}),"\n",(0,i.jsxs)(n.p,{children:["Taking k-Hop as an example, the incremental algorithm works as follows: In the first iteration, all edges in the incremental graph are identified and treated as initial incoming and outgoing paths, which are sent to their start and end vertices. In subsequent iterations, these paths are extended. Once the desired hop count is reached, the paths are sent back to the starting vertex, where they are combined into final results. Detailed implementation can be found in the open-source repository file ",(0,i.jsx)(n.a,{href:"https://github.com/TuGraph-family/tugraph-analytics/blob/master/geaflow/geaflow-dsl/geaflow-dsl-plan/src/main/java/com/antgroup/geaflow/dsl/udf/graph/IncKHopAlgorithm.java",children:"IncKHopAlgorithm.java"}),"."]}),"\n",(0,i.jsx)(n.p,{children:"The diagram below illustrates the two-hop case. In the first iteration, the edge B->C creates incoming and outgoing paths, sent to B and C, respectively. In the second iteration, B receives an incoming path, adds its own incoming edges, and forms a 2-hop incoming path, which it sends to itself. Similarly, C forms a 2-hop outgoing path and sends it to B. In the final iteration, B combines the incoming and outgoing paths to produce the new paths. Unlike Flink, which must scan all historical relationships, GeaFlow's computation is proportional to the incremental paths, not the historical data."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/35234/1741710927215-b6be1398-7485-432b-b8f7-c4cde5366302.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"Two-Hop Incremental Path Computation"}),"\n",(0,i.jsxs)(n.p,{children:["The above graph algorithm has been integrated into GeaFlow\u2019s ",(0,i.jsx)(n.code,{children:"IncKHop"})," operator, and users can directly call it using DSL:"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-sql",children:"set geaflow.dsl.max.traversal=4;\nset geaflow.dsl.table.parallelism=4;\n\nCREATE GRAPH modern (\n  Vertex node (\n    id int ID\n  ),\n  Edge relation (\n    srcId int SOURCE ID,\n    targetId int DESTINATION ID\n  )\n) WITH (\n  storeType='rocksdb',\n  shardCount = 4\n);\n\nCREATE TABLE web_google_20 (\n  src varchar,\n  dst varchar\n) WITH (\n  type='file',\n  geaflow.dsl.table.parallelism='4',\n  geaflow.dsl.column.separator='\\t',\n  `geaflow.dsl.source.file.parallel.mod`='true',\n  geaflow.dsl.file.path = 'resource:///data/web-google-20',\n  geaflow.dsl.window.size = 8\n);\n\nINSERT INTO modern.node\nSELECT cast(src as int)\nFROM web_google_20\n;\n\nINSERT INTO modern.node\nSELECT cast(dst as int)\nFROM web_google_20\n;\n\nINSERT INTO modern.relation\nSELECT cast(src as int), cast(dst as int)\nFROM web_google_20;\n;\n\nCREATE TABLE tbl_result (\n  ret varchar\n) WITH (\n  type='file',\n  geaflow.dsl.file.path='${target}'\n);\n\nUSE GRAPH modern;\n\nINSERT INTO tbl_result\nCALL inc_khop(2) YIELD (ret)\nRETURN ret\n;\n"})}),"\n",(0,i.jsx)(n.h2,{id:"geaflow-performance-test",children:"GeaFlow Performance Test"}),"\n",(0,i.jsxs)(n.p,{children:["To evaluate GeaFlow\u2019s performance in stream graph computing, we designed a comparative experiment using the k-Hop algorithm. We used the public dataset ",(0,i.jsx)(n.a,{href:"https://snap.stanford.edu/data/web-Google.html",children:"web-Google.txt"})," as input and measured the time required to complete the computation across one-hop to four-hop scenarios. The experiment ran on 16 servers, each with 8 cores and 16GB memory."]}),"\n",(0,i.jsx)(n.p,{children:"As shown in the results below, the x-axis represents one-hop to four-hop relationships, and the y-axis shows the processing time on a logarithmic scale. In one- and two-hop cases, Flink outperforms GeaFlow due to the small amount of data involved in joins. However, as complexity increases, Flink\u2019s join-based approach becomes inefficient, especially in four-hop cases, where it can\u2019t finish within a day. GeaFlow, by contrast, scales efficiently due to its incremental graph algorithm, whose performance depends only on the incremental paths."}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://intranetproxy.alipay.com/skylark/lark/0/2025/png/8237/1743568484086-10eb9a1a-3dd0-42ee-b885-875ac7d81221.png",alt:""})}),"\n",(0,i.jsx)(n.p,{children:"k-Hop Computation Performance Comparison"}),"\n",(0,i.jsx)(n.h2,{id:"conclusion-and-future-work",children:"Conclusion and Future Work"}),"\n",(0,i.jsx)(n.p,{children:"Traditional stream engines like Flink use join operators for relationship computation, which requires scanning all historical data, resulting in poor performance in large-scale associative scenarios. GeaFlow addresses this by introducing graph computing into stream processing through a stream graph framework, significantly boosting performance with incremental graph algorithms."}),"\n",(0,i.jsx)(n.p,{children:"GeaFlow is now open-source. We aim to build a unified lakehouse engine for graph data to support diverse associative analytics. We are also preparing to join the Apache Software Foundation to enrich the open-source big data ecosystem. If you're interested in graph technology, we welcome you to join the community."}),"\n",(0,i.jsx)(n.p,{children:"There are many exciting tasks to explore. You can start with these beginner-friendly issues:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["Support incremental k-Core algorithm (",(0,i.jsx)(n.a,{href:"https://github.com/TuGraph-family/tugraph-analytics/issues/466",children:"Issue 466"}),")"]}),"\n",(0,i.jsxs)(n.li,{children:["Support incremental Minimum Spanning Tree algorithm (",(0,i.jsx)(n.a,{href:"https://github.com/TuGraph-family/tugraph-analytics/issues/465",children:"Issue 465"}),")"]}),"\n",(0,i.jsx)(n.li,{children:"..."}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"references",children:"References"}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsxs)(n.li,{children:["GeaFlow Project: ",(0,i.jsx)(n.a,{href:"https://github.com/TuGraph-family/tugraph-analytics",children:"https://github.com/TuGraph-family/tugraph-analytics"})]}),"\n",(0,i.jsxs)(n.li,{children:["web-Google Dataset: ",(0,i.jsx)(n.a,{href:"https://snap.stanford.edu/data/web-Google.html",children:"https://snap.stanford.edu/data/web-Google.html"})]}),"\n",(0,i.jsxs)(n.li,{children:["GeaFlow Issues: ",(0,i.jsx)(n.a,{href:"https://github.com/TuGraph-family/tugraph-analytics/issues",children:"https://github.com/TuGraph-family/tugraph-analytics/issues"})]}),"\n",(0,i.jsxs)(n.li,{children:["Incremental k-Hop Source Code: ",(0,i.jsx)(n.a,{href:"https://github.com/TuGraph-family/tugraph-analytics/blob/master/geaflow/geaflow-dsl/geaflow-dsl-plan/src/main/java/com/antgroup/geaflow/dsl/udf/graph/IncKHopAlgorithm.java",children:"https://github.com/TuGraph-family/tugraph-analytics/blob/master/geaflow/geaflow-dsl/geaflow-dsl-plan/src/main/java/com/antgroup/geaflow/dsl/udf/graph/IncKHopAlgorithm.java"})]}),"\n"]})]})}function p(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>s,x:()=>o});var a=t(6540);const i={},r=a.createContext(i);function s(e){const n=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(r.Provider,{value:n},e.children)}}}]);